// lib/fontes.mjs — simula as APIs externas da empresa BuscaJá.
// Cada fonte é lenta (como uma API de verdade na internet): ela só
// responde DEPOIS de um atraso, em milissegundos.

// Resolve com { nome, dado } depois de `atrasoMs` milissegundos.
export function buscarFonte(nome, atrasoMs, dado) {
  return new Promise((resolve) => {
    setTimeout(() => resolve({ nome, dado }), atrasoMs);
  });
}

// Rejeita com erro contendo o nome da fonte depois de `atrasoMs`.
export function buscarFonteQueFalha(nome, atrasoMs) {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error('fonte ' + nome + ' fora do ar')), atrasoMs);
  });
}

