// lib/agregador.mjs — junta as respostas de várias fontes ao mesmo tempo.
import { buscarFonte, buscarFonteQueFalha } from './fontes.mjs';

// Transforma a lista de fontes numa lista de promises (todas já disparadas).
function dispararBuscas(fontes) {
  return fontes.map((fonte) =>
    fonte.falha
      ? buscarFonteQueFalha(fonte.nome, fonte.atrasoMs)
      : buscarFonte(fonte.nome, fonte.atrasoMs, fonte.dado),
  );
}

// Tudo ou nada: se QUALQUER fonte falhar, a busca inteira rejeita.
export function buscarTodas(fontes) {
  return Promise.all(dispararBuscas(fontes));
}

// Tolerante a falhas: devolve só as respostas de quem conseguiu responder.
export function buscarTolerante(fontes) {
  return Promise.allSettled(dispararBuscas(fontes)).then((resultados) =>
    resultados
      .filter((r) => r.status === 'fulfilled')
      .map((r) => r.value),
  );
}

// Limite de tempo: quem vencer primeiro define o resultado.
export function buscarComTimeout(fontes, limiteMs) {
  const busca = buscarTodas(fontes);
  const estouro = new Promise((_, reject) => {
    setTimeout(() => reject(new Error('tempo esgotado: ' + limiteMs + 'ms')), limiteMs);
  });
  return Promise.race([busca, estouro]);
}

