import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buscarFonte, buscarFonteQueFalha } from './lib/fontes.mjs';
import { buscarTodas, buscarTolerante, buscarComTimeout } from './lib/agregador.mjs';

const fontesOk = [
  { nome: 'precos', atrasoMs: 4, dado: 'R$ 99,90' },
  { nome: 'estoque', atrasoMs: 6, dado: '12 unidades' },
];

test('buscarFonte responde com { nome, dado } depois do atraso', async () => {
  assert.deepEqual(await buscarFonte('precos', 2, 'R$ 99,90'), {
    nome: 'precos',
    dado: 'R$ 99,90',
  });
});

test('buscarFonteQueFalha rejeita com o nome da fonte', async () => {
  await assert.rejects(() => buscarFonteQueFalha('frete', 2), /frete fora do ar/);
});

test('buscarTodas devolve as respostas de todas as fontes ao mesmo tempo', async () => {
  const comeco = Date.now();
  const respostas = await buscarTodas(fontesOk);
  const decorrido = Date.now() - comeco;
  assert.deepEqual(respostas, [
    { nome: 'precos', dado: 'R$ 99,90' },
    { nome: 'estoque', dado: '12 unidades' },
  ]);
  // Em paralelo, o tempo total é o da fonte MAIS LENTA (6ms), não a soma (10ms).
  assert.ok(decorrido < 10, 'as buscas devem acontecer ao mesmo tempo (paralelas)');
});

test('buscarTodas rejeita quando uma fonte falha', async () => {
  await assert.rejects(
    () => buscarTodas([...fontesOk, { nome: 'frete', atrasoMs: 4, falha: true }]),
    /frete fora do ar/,
  );
});

test('buscarTolerante devolve só as fontes que responderam', async () => {
  const respostas = await buscarTolerante([
    ...fontesOk,
    { nome: 'frete', atrasoMs: 4, falha: true },
  ]);
  assert.deepEqual(respostas, [
    { nome: 'precos', dado: 'R$ 99,90' },
    { nome: 'estoque', dado: '12 unidades' },
  ]);
});

test('buscarComTimeout resolve quando dá tempo e rejeita quando estoura', async () => {
  const rapidas = await buscarComTimeout(fontesOk, 10);
  assert.equal(rapidas.length, 2);
  await assert.rejects(
    () =>
      buscarComTimeout(
        [...fontesOk, { nome: 'lenta', atrasoMs: 8, dado: 'x' }],
        4,
      ),
    /tempo esgotado/,
  );
});
